```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let urls = match aap::caps::state_read::get("subscriptions") {
            Some(raw) => raw
                .lines()
                .map(str::trim)
                .filter(|line| !line.is_empty())
                .map(String::from)
                .collect(),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
```

I left out the enrichment fetch to `https://metadata.internal.example/enrich`. That call needs `aap:caps/http-client`, which is not in this node's `with` clause (only `aap:caps/state-read@0.1.0` is granted), so importing it would exceed the node's authority. If that enrichment is needed, it belongs in a node that is granted HTTP access, or the grant for this node has to be widened.

